SourceCode.Declaration:
public final class METTMSEngineHeaderContract
{   
    METTMSSourceRecordHeaderMap sourceRecord;
    Common extensionTable;
    TMSCarrierCode carrierCode;
    CustAccount custAccount;
    METOrderSplitGroup splitGroup;
    str shippingDateStr;
    METRoute route;
    boolean execOrder = false;

    TransDate shipDate;
    METRouteStopNum routeStop;
    METInventTransferTableExt inventTransferTableExt;

}

Method.Source:
public static METTMSEngineHeaderContract construct(METTMSSourceRecordHeaderMap _sourceRecord)
{
    METTMSEngineHeaderContract contract = new METTMSEngineHeaderContract();

    contract.sourceRecord = _sourceRecord;
    contract.init();

    return contract;
}

public void init()
{
    if(sourceRecord.TableID == tableNum(InventTransferTable))
    {
        inventTransferTableExt = METInventTransferTableExt::findByTransferId(sourceRecord.OrderId);
    }

}

public METTMSSourceRecordHeaderMap parmSourceRecord(METTMSSourceRecordHeaderMap _sourceRecord = sourceRecord)
{
    sourceRecord = _sourceRecord;

    return sourceRecord;
}

/// <summary>
/// Returns the carried code of the order
/// </summary>
public TMSCarrierCode getCarrierCode()
{
    if(carrierCode != '')
    {
        return carrierCode;
    }
    if(sourceRecord.TableId == tableNum(SalesTable))
    {
        carrierCode = TMSSalesTable::find(sourceRecord.OrderId).CarrierCode;
    }
    else if(sourceRecord.TableId == tableNum(InventTransferTable))
    {
        carrierCode = TMSInventTransferTable::find(sourceRecord.OrderId).CarrierCode;
    }

    return carrierCode;
}

public CustAccount getCustomerAccount()
{
    if(custAccount != '')
    {
        return custAccount;
    }

    if(sourceRecord.TableId == tableNum(SalesTable))
    {
        custAccount = sourceRecord.CustomerAccount;
    }
    else if(sourceRecord.TableId == tableNum(InventTransferTable))
    {
        custAccount = METInventLocation::findByInventLocationId(sourceRecord.InventLocationTo).InternalCustomer;
    }

    return custAccount;
}

/// <summary>
/// Returns the extension tables
/// </summary>
public METOrderSplitGroup getOrderSplitGroup()
{
    if(splitGroup != '')
    {
        return splitGroup;
    }

    if(sourceRecord.TableId == tableNum(SalesTable))
    {
        splitGroup = METSalesTable::findByRefRecId(sourceRecord.RecId).OrderSplitGroup;
    }
    else if(sourceRecord.TableId == tableNum(InventTransferTable))
    {
        splitGroup = inventTransferTableExt.OrderSplitGroup;
    }

    return splitGroup;
}

/// <summary>
/// Returns the extension tables
/// </summary>
public Common getExtensionTable()
{
    if(extensionTable)
    {
        return extensionTable;
    }

    if(sourceRecord.TableId == tableNum(SalesTable))
    {
        extensionTable = METSalesTable::findByRefRecId(sourceRecord.RecId);
    }
    else if(sourceRecord.TableId == tableNum(InventTransferTable))
    {
        extensionTable = inventTransferTableExt;
    }

    return extensionTable;
}

public METTMSShipmentID getShipmentID()
{

    if(shippingDateStr != '')
    {
        return shippingDateStr;
    }

    shippingDateStr = date2Str
        (this.getShipDate(),
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

    str comp2 = sourceRecord.TableId == tableNum(SalesTable) ? sourceRecord.CustomerAccount : sourceRecord.InventLocationTo;

    return strFmt("@MET:ShipmentStrFmt",
        sourceRecord.InventLocationFrom,
        comp2,
        this.getRoute(),
        shippingDateStr);
}

/// <summary>
/// Retrive the route id of the order and return it
/// </summary>
public METRoute getRoute()
{
    if(route != '')
    {
        return route;
    }
    if(sourceRecord.TableId == tableNum(SalesTable))
    {
        route = sourceRecord.Route;
    }
    else if(sourceRecord.TableId == tableNum(InventTransferTable))
    {
        route = inventTransferTableExt.Route;
    }

    return route;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public boolean isOrderExcluded()
{
    METSalesOrderTypes  salesOrderTypes;
    boolean ret = false;

    if(sourceRecord.TableId == tableNum(SalesTable))
    {
        salesOrderTypes = METSalesOrderTypes::find(sourceRecord.OrderType);

        if (salesOrderTypes.RecId)
        {
            ret = salesOrderTypes.ExcludeFromTMSEngine;
        }
    }
    else if(sourceRecord.TableId == tableNum(InventTransferTable))
    {
        ret = false;
    }

    return ret;
}

/// <summary>
/// Gets the shipping date of the order, if the Confirmed ship date is not available then returns the requested ship date of the sales order.
/// </summary>
public TransDate getShipDate()
{
    shipDate = sourceRecord.ConfirmedShipDate;

    if(sourceRecord.TableId == tableNum(SalesTable) && !shipDate)
    {
        shipDate = sourceRecord.RequestedShipDate;
    }

    return shipDate;
}

public TransDate getReceiptDate()
{
    TransDate receiptDate;

    receiptDate = sourceRecord.ConfirmedReceiptDate;

    if(sourceRecord.TableId == tableNum(SalesTable) && !receiptDate)
    {
        receiptDate = sourceRecord.RequestedReceiptDate;
    }

    return receiptDate;
}

/// <summary>
/// Get the destination type of the shipment.
/// </summary>
/// <returns>Customer if this a sales, otherwise warehouse</returns>
public METDestinationType getDestinationType()
{
    METDestinationType ret;

    if (sourceRecord.TableId == tableNum(SalesTable))
    {
        ret = METDestinationType::Customer;
    }
    else if (sourceRecord.TableId == tableNum(InventTransferTable))
    {
        ret = METDestinationType::Warehouse;
    }

    return ret;
}

/// <summary>
/// Gets the route stop number of the order
/// </summary>
public METRouteStopNum getRouteStop()
{
    if (sourceRecord.TableId == tableNum(SalesTable))
    {
        routeStop = sourceRecord.RouteStop;
    }

    else if (sourceRecord.TableId == tableNum(InventTransferTable))
    {
        routeStop = inventTransferTableExt.RouteStopNum;
    }

    return routeStop;
}
